        const bt = CARD_TUNING.bank_shot;
        this.spawn(f.side, "bank", w, x, z, yaw, bt.speed, Math.min(t.cap, bt.damage * t.mult * od), bt.radius, bt.range, __spreadProps(__spreadValues({}, opts), { heavy: true, knockback: bt.knockback * 0.5, bounces: 1 }));
